                                '[data-testid="stPopoverBody"], [data-pdf-export-control="true"], ' +
                                '[data-testid^="stElementToolbar"], ' +
                                '[data-testid="stTooltipHoverTarget"], ' +
                                '[data-testid="stBaseButton-elementToolbar"], ' +
                                '[data-testid="stVegaLiteChart"] details'
